                if (ph != 0) {
                    s2 = PdDint(src, ar, dc, a, b, st, ph, Pdfnames.PnPredictor(), 1);
                    Pdflex.PlAppendInt(ar, plan, s2);
                    s2 = PdDint(src, ar, dc, a, b, st, ph, Pdfnames.PnColors(), 1);
                    Pdflex.PlAppendInt(ar, plan, s2);
                    s2 = PdDint(src, ar, dc, a, b, st, ph, Pdfnames.PnBitsPerComponent(), 8);
                    Pdflex.PlAppendInt(ar, plan, s2);
                    s2 = PdDint(src, ar, dc, a, b, st, ph, Pdfnames.PnColumns(), 1);
                    Pdflex.PlAppendInt(ar, plan, s2);
                    s2 = PdDint(src, ar, dc, a, b, st, ph, Pdfnames.PnEarlyChange(), 1);
                    Pdflex.PlAppendInt(ar, plan, s2);
                } else {
                    Pdflex.PlAppendInt(ar, plan, 1);
                    Pdflex.PlAppendInt(ar, plan, 1);
                    Pdflex.PlAppendInt(ar, plan, 8);
                    Pdflex.PlAppendInt(ar, plan, 1);
                    Pdflex.PlAppendInt(ar, plan, 1);
                }
                nst += 1;
                i += 1;
            }
        }
        Pdflex.PlSetInt(ar, sth, status);
        Pdflex.PlSetInt(ar, nsh, nst);
        return plan;
    }
    public static int PdRunPlan(byte[] src, emon.Port.Cells ar, int plan, int sh, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells @out) {
        // Run a plan over stream `sh` into `out` (cleared first), with `b` and
        // `st` as scratch. Answers a `pf-status`: the FIRST error, from a
        // stage or from the plan; whatever was decoded stays in `out`. An
        // image codec (DCT, JPX, CCITT, JBIG2) stops the chain: `image-filter`
        // (10), with `out` holding the data as it was when the codec was
        // reached. `out`, `b` and `st` must be three different cells.
        int start = Pdflex.PlStreamStart(ar, sh);
        int end = start + Pdflex.PlStreamLen(ar, sh);
        int h0 = Pdflex.PlFirst(ar, plan);
        int h1 = Pdflex.PlNext(ar, h0);
        int pstatus = Pdflex.PlIntValue(ar, h0);
        int ns = Pdflex.PlIntValue(ar, h1);
        int k = Pdflex.PlNext(ar, h1);
        int i = 0;
        int cur = 0;
        int status = 0;
        int s2 = 0;
        int code = 0;
        int pred = 1;
        int colors = 1;
        int bpc = 8;
        int columns = 1;
        int early = 1;
        emon.Port.CellsDrop(@out, 0);
        while (i < ns) {
            code = Pdflex.PlIntValue(ar, k);
            k = Pdflex.PlNext(ar, k);
            pred = Pdflex.PlIntValue(ar, k);
            k = Pdflex.PlNext(ar, k);
            colors = Pdflex.PlIntValue(ar, k);
            k = Pdflex.PlNext(ar, k);
            bpc = Pdflex.PlIntValue(ar, k);
            k = Pdflex.PlNext(ar, k);
            columns = Pdflex.PlIntValue(ar, k);
            k = Pdflex.PlNext(ar, k);
            early = Pdflex.PlIntValue(ar, k);
            k = Pdflex.PlNext(ar, k);
            // An image codec: hand back what there is, undecoded.
            if ((code >= 7) && (code <= 10)) {
                if (cur == 0) {
                    PdSpan(src, start, end, @out);
                }
                if (cur == 2) {
                    PdCopy(b, @out);
                }
                if (status == 0) {
                    return 10;
                }
                return status;
            }
            // cur: 0 the file's span, 1 the data is in out, 2 it is in b.
            if (cur == 0) {
                s2 = Pdffilter.PfRun(code, src, start, end, @out, st, early);
                cur = 1;
            } else if (cur == 1) {
                emon.Port.CellsDrop(b, 0);
                s2 = Pdffilter.PfRun(code, emon.Port.CellsBytes(@out), 0, emon.Port.CellsLen(@out), b, st, early);
                cur = 2;
            } else {
                emon.Port.CellsDrop(@out, 0);
                s2 = Pdffilter.PfRun(code, emon.Port.CellsBytes(b), 0, emon.Port.CellsLen(b), @out, st, early);
                cur = 1;
            }
            if (status == 0) {
                status = s2;
            }
            // The predictor, for the two filters that have one.
            s2 = 0;
            if ((pred > 1) && ((code == 3) || (code == 4))) {
                if (cur == 1) {
                    emon.Port.CellsDrop(b, 0);
                    s2 = Pdffilter.PfPredict(@out, 0, emon.Port.CellsLen(@out), b, pred, colors, bpc, columns);
                    cur = 2;
                } else {
                    emon.Port.CellsDrop(@out, 0);
                    s2 = Pdffilter.PfPredict(b, 0, emon.Port.CellsLen(b), @out, pred, colors, bpc, columns);
                    cur = 1;
                }
            }
            if (status == 0) {
                status = s2;
            }
            i += 1;
        }
        if (ns == 0) {
            PdSpan(src, start, end, @out);
        }
        if (cur == 2) {
            PdCopy(b, @out);
        }
        if (status == 0) {
            status = pstatus;
        }
        return status;
    }
    public static int PdStreamData(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int sh, emon.Port.Cells @out) {
        // The DECODED bytes of stream `sh` into `out` (cleared first), by
        // planning the chain and running it. `out` must not be `a`, `b` or
        // `st` (they are overwritten); answers a `pf-status`, the first error.
        int plan = PdStreamPlan(src, ar, dc, a, b, st, sh);
        return PdRunPlan(src, ar, plan, sh, b, st, @out);
    }
    internal static int PdAddTrailer(emon.Port.Cells dc, int dict) {
        int n = emon.Port.CellsAt(dc, DNtrail);
        if (n < 16) {
            emon.Port.CellsSet(dc, DTrail + n, dict);
            emon.Port.CellsSet(dc, DNtrail, n + 1);
        }
        return 0;
    }
    internal static int PdTrailerGet(emon.Port.Cells ar, emon.Port.Cells dc, int id) {
        // The first value under a well-known key among the trailers, newest
        // first, or 0. (An incremental update's trailer repeats /Root; a
        // damaged one may not.)
        int i = 0;
        int v = 0;
        while (i < emon.Port.CellsAt(dc, DNtrail)) {
            v = Pdflex.PlDictGet(ar, emon.Port.CellsAt(dc, DTrail + i), id);
            if (v != 0) {
                return v;
            }
            i += 1;
        }
        return 0;
    }
    internal static int PdSetPrev(emon.Port.Cells ar, emon.Port.Cells dc, int dict) {
        // Remember the /Prev of the trailer just read, for the chain.
        int p = Pdflex.PlDictGet(ar, dict, Pdfnames.PnPrev());
        if ((p != 0) && (Pdflex.PlKindOf(ar, p) == 2)) {
            if (Pdflex.PlIntValue(ar, p) >= 0) {
                emon.Port.CellsSet(dc, DPrev, Pdflex.PlIntValue(ar, p));
            }
        }
        return 0;
    }
    internal static int PdTable(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int pos) {
        // A classic section: `xref`, subsections `first count` of `offset gen
        // n|f` entries, `trailer`, the trailer dictionary. Entries are read
        // as tokens, so the 20-byte layout is not insisted on. A count larger
        // than its entries ends at `trailer`; a first number of 1 over an
        // entry that is the free head (65535) means 0. The trailer's /XRefStm
        // (a hybrid file) is read here, over the free entries of this table.
        int n = Pdfsrc.PsLen(src);
        int tk = 0;
        int first = 0;
        int count = 0;
        int i = 0;
        int eoff = 0;
        int egen = 0;
        int ek = 0;
        int more = 1;
        int inner = 1;
        int d = 0;
        int xpos = 0;
        int xs = 0;
        Pdflex.PlSeek(ar, pos, n);
        tk = Pdflex.PlLex(src, ar);
        while (more == 1) {
            tk = Pdflex.PlLex(src, ar);
            if ((tk == 11) && (Pdflex.PlTokenC(ar) == 10)) {
                more = 0;
            } else {
                if (tk != 1) {
                    return 3;
                }
                first = Pdflex.PlTokenA(ar);
                tk = Pdflex.PlLex(src, ar);
                if (tk != 1) {
                    return 3;
                }
                count = Pdflex.PlTokenA(ar);
                i = 0;
                inner = 1;
                while ((i < count) && (inner == 1)) {
                    tk = Pdflex.PlLex(src, ar);
                    if ((tk == 11) && (Pdflex.PlTokenC(ar) == 10)) {
                        Pdflex.PlUnread(ar);
                        inner = 0;
                    } else {
                        if (tk != 1) {
                            return 3;
                        }
                        eoff = Pdflex.PlTokenA(ar);
                        tk = Pdflex.PlLex(src, ar);
                        if (tk != 1) {
                            return 3;
                        }
                        egen = Pdflex.PlTokenA(ar);
                        tk = Pdflex.PlLex(src, ar);
                        if (tk != 11) {
                            return 3;
                        }
                        ek = Pdflex.PlTokenC(ar);
                        if ((ek != 12) && (ek != 13)) {
                            return 3;
                        }
                        if ((i == 0) && (first == 1) && (ek == 12) && (egen == 65535)) {
                            first = 0;
                        }
                        if (ek == 13) {
                            PdEntPut(dc, first + i, 2, eoff, egen, 0);
                        } else {
                            PdEntPut(dc, first + i, 1, eoff, egen, 0);
                        }
                        i += 1;
                    }
                }
            }
        }
        d = Pdflex.PlParse(src, ar);
        if (d == 0) {
            return 3;
        }
        if (Pdflex.PlKindOf(ar, d) != 7) {
            return 3;
        }
        PdAddTrailer(dc, d);
        PdSetPrev(ar, dc, d);
        xs = Pdflex.PlDictGet(ar, d, Pdfnames.PnXRefStm());
        if ((xs != 0) && (Pdflex.PlKindOf(ar, xs) == 2)) {
            PdWarnSet(dc, 2);
            // An unreadable /XRefStm costs only the objects it lists.
            xpos = Pdflex.PlIntValue(ar, xs) + emon.Port.CellsAt(dc, DShift);
            PdXstream(src, ar, dc, a, b, st, xpos, 1);
        }
        return 0;
    }
    internal static int PdRd(emon.Port.Cells c, int at, int w) {
        // A big-endian unsigned field of w bytes (0 to 4) from a Cells of
        // bytes; four bytes with the high bit set saturate at 2^31-1.
        int v = 0;
        int k = 0;
        if ((w == 4) && (emon.Port.CellsAt(c, at) >= 128)) {
            return 2147483647;
        }
        while (k < w) {
            v = (v * 256) + emon.Port.CellsAt(c, at + k);
            k += 1;
        }
        return v;
    }
    internal static int PdIval(emon.Port.Cells ar, int h) {
        // An integer object's value, or -1 for anything else (and for 0).
        if (h == 0) {
            return -1;
        }
        if (Pdflex.PlKindOf(ar, h) == 2) {
            return Pdflex.PlIntValue(ar, h);
        }
        return -1;
    }
    internal static int PdXfill(emon.Port.Cells dc, emon.Port.Cells a, int at0, int first, int count, int w0, int w1, int w2, int mode) {
        // Read `count` entries from the decoded bytes `a`, starting at byte
        // at0, as objects first, first+1, ... Answers the byte index after
        // the last entry read; entries stop where the data does.
        int ln = emon.Port.CellsLen(a);
        int rec = (w0 + w1) + w2;
        int at = at0;
        int k = 0;
        int ty = 0;
        int f1 = 0;
        int f2 = 0;
        if ((first < 0) || (count < 0)) {
            return at0;
        }
        while ((k < count) && ((at + rec) <= ln)) {
            ty = 1;
            if (w0 > 0) {
                ty = PdRd(a, at, w0);
            }
            f1 = PdRd(a, at + w0, w1);
            f2 = PdRd(a, (at + w0) + w1, w2);
            if (ty == 0) {
                PdEntPut(dc, first + k, 1, f1, f2, mode);
            }
            if (ty == 1) {
                PdEntPut(dc, first + k, 2, f1, f2, mode);
            }
            if (ty == 2) {
                PdEntPut(dc, first + k, 3, f1, f2, mode);
            }
            at += rec;
            k += 1;
        }
        return at;
    }
    internal static int PdXfinish(emon.Port.Cells ar, emon.Port.Cells dc, int d, int mode) {
        // A chain section (mode 0) registers its dictionary as a trailer and
        // names its /Prev; an /XRefStm (mode 1) does neither.
        if (mode == 0) {
            PdAddTrailer(dc, d);
            PdSetPrev(ar, dc, d);
            PdWarnSet(dc, 16);
        }
        return 0;
    }
    internal static int PdXstream(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int pos, int mode) {
        // A cross-reference STREAM: a stream object whose decoded data is
        // entries of widths /W [t o g] for each (first, count) of /Index
        // (default [0 /Size]): type 0 free, 1 in use (offset, generation), 2
        // in an object stream (stream number, index); an absent type field is
        // type 1. Widths are 0 to 4 bytes. Mode 1 (an /XRefStm) writes over
        // free entries and adds no trailer; mode 0 is a section of the chain.
        int n = Pdfsrc.PsLen(src);
        int h = 0;
        int d = 0;
        int wa = 0;
        int w0 = 0;
        int w1 = 0;
        int w2 = 0;
        int ix = 0;
        int ip = 0;
        int first = 0;
        int count = 0;
        int size = 0;
        int at = 0;
        int plan = 0;
        int status = 0;
        int e0 = 0;
        int e1 = 0;
        int e2 = 0;
        Pdflex.PlSeek(ar, pos, n);
        h = Pdflex.PlParseIndirect(src, ar, pos);
        if (h == 0) {
            return 3;
        }
        if (Pdflex.PlKindOf(ar, h) != 8) {
            return 3;
        }
        d = Pdflex.PlStreamDict(ar, h);
        wa = PdDget(src, ar, dc, a, b, st, d, Pdfnames.PnW());
        if (wa == 0) {
            return 3;
        }
        if (Pdflex.PlKindOf(ar, wa) != 6) {
            return 3;
        }
        if (Pdflex.PlCount(ar, wa) < 3) {
            return 3;
        }
        e0 = PdNth(ar, wa, 0);
        e1 = PdNth(ar, wa, 1);
        e2 = PdNth(ar, wa, 2);
        w0 = PdIval(ar, e0);
        w1 = PdIval(ar, e1);
        w2 = PdIval(ar, e2);
        if ((w0 < 0) || (w0 > 4) || (w1 < 0) || (w1 > 4) || (w2 < 0) || (w2 > 4)) {
            return 3;
        }
        if (((w0 + w1) + w2) == 0) {
            return 3;
        }
        size = PdDint(src, ar, dc, a, b, st, d, Pdfnames.PnSize(), 0);
        plan = PdStreamPlan(src, ar, dc, a, b, st, h);
        status = PdRunPlan(src, ar, plan, h, b, st, a);
        // A cut-short or badly-checksummed stream still holds entries.
        if ((status != 0) && (status != 1) && (status != 5) && (status != 7)) {
            return 3;
        }
        ix = PdDget(src, ar, dc, a, b, st, d, Pdfnames.PnIndex());
        if ((ix != 0) && (Pdflex.PlKindOf(ar, ix) == 6)) {
            ip = Pdflex.PlFirst(ar, ix);
            while (ip != 0) {
                first = PdIval(ar, ip);
                ip = Pdflex.PlNext(ar, ip);
                if (ip != 0) {
                    count = PdIval(ar, ip);
                    ip = Pdflex.PlNext(ar, ip);
                    at = PdXfill(dc, a, at, first, count, w0, w1, w2, mode);
                }
            }
        } else {
            PdXfill(dc, a, 0, 0, size, w0, w1, w2, mode);
        }
        return PdXfinish(ar, dc, d, mode);
    }
    internal static int PdSection(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int off) {
        // Read the section at file offset `off` (shifted): a table or a stream.
        int pos = off + emon.Port.CellsAt(dc, DShift);
        int k = PdKindAt(src, ar, pos);
        if (k == 1) {
            return PdTable(src, ar, dc, a, b, st, pos);
        }
        if (k == 2) {
            return PdXstream(src, ar, dc, a, b, st, pos, 0);
        }
        return 3;
    }
    internal static int PdChain(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int off0) {
        // The sections, newest first: the one `startxref` names, then each
        // /Prev. A section already read ends the chain (a loop); a failure in
        // the first section is the answer, in a later one only a warning: the
        // newer sections stand.
        int off = off0;
        int guard = 0;
        int status = 0;
        int j = 0;
        int seen = 0;
        while ((off >= 0) && (guard < 64)) {
            seen = 0;
            j = 0;
            while (j < emon.Port.CellsAt(dc, DNseen)) {
                if (emon.Port.CellsAt(dc, DSeen + j) == off) {
                    seen = 1;
                }
                j += 1;
            }
            if (seen == 1) {
                PdWarnSet(dc, 4);
                off = -1;
            } else {
                emon.Port.CellsSet(dc, DSeen + guard, off);
                emon.Port.CellsSet(dc, DNseen, guard + 1);
                emon.Port.CellsSet(dc, DPrev, -1);
                status = PdSection(src, ar, dc, a, b, st, off);
                if (status != 0) {
                    if (guard == 0) {
                        return status;
                    }
                    PdWarnSet(dc, 8);
                    off = -1;
                } else {
                    off = emon.Port.CellsAt(dc, DPrev);
                }
                guard += 1;
            }
        }
        return 0;
    }
    internal static int PdUnreadable(emon.Port.Cells dc, int status) {
        // The status to answer when the catalog or the page tree could not be
        // read: `encrypted` (6) if the trailer has /Encrypt, else `status`.
        if (emon.Port.CellsAt(dc, DEnc) != 0) {
            return 6;
        }
        return status;
    }
    public static int PdOpen(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st) {
        // Open a document: find the header and `startxref`, read every
        // cross-reference section and trailer, check that there is a catalog
        // with a page tree. Answers a `pd-status` (0 ok). Nothing is decoded
        // but the cross-reference streams and what they need.
        Pdflex.PlInit(ar);
        PdInit(dc);
        int n = Pdfsrc.PsLen(src);
        int @base = PdFindHeader(src);
        int sx = 0;
        int off = 0;
        int tk = 0;
        int lim = 0;
        int status = 0;
        int root = 0;
        int pages = 0;
        int enc = 0;
        if (@base < 0) {
            return 1;
        }
        emon.Port.CellsSet(dc, DBase, @base);
        if ((@base + 7) < n) {
            emon.Port.CellsSet(dc, DVmaj, Pdfsrc.PsU8(src, @base + 5) - 48);
            emon.Port.CellsSet(dc, DVmin, Pdfsrc.PsU8(src, @base + 7) - 48);
        }
        lim = emon.Port.LimitOf(3);
        if (n < 16000000) {
            if (lim > (65536 + (64 * n))) {
                lim = 65536 + (64 * n);
            }
        }
        emon.Port.CellsSet(dc, DLiment, lim);
        emon.Port.CellsSet(dc, DReflim, emon.Port.LimitOf(4));
        sx = PdFindStartxref(src);
        if (sx < 0) {
            return 2;
        }
        Pdflex.PlSeek(ar, sx + 9, n);
        tk = Pdflex.PlLex(src, ar);
        if (tk != 1) {
            return 3;
        }
        off = Pdflex.PlTokenA(ar);
        // Offsets are from the start of the file, or (junk before the header)
        // from the header: whichever finds a section at `startxref`.
        if (PdKindAt(src, ar, off) != 0) {
            emon.Port.CellsSet(dc, DShift, 0);
        } else if ((@base > 0) && (PdKindAt(src, ar, off + @base) != 0)) {
            emon.Port.CellsSet(dc, DShift, @base);
            PdWarnSet(dc, 1);
        } else {
            return 3;
        }
        status = PdChain(src, ar, dc, a, b, st, off);
        if (status != 0) {
            return status;
        }
        if (emon.Port.CellsAt(dc, DNtrail) == 0) {
            return 3;
        }
        enc = PdTrailerGet(ar, dc, Pdfnames.PnEncrypt());
        if (enc != 0) {
            emon.Port.CellsSet(dc, DEnc, enc);
        }
        root = PdTrailerGet(ar, dc, Pdfnames.PnRoot());
        if (root == 0) {
            return 4;
        }
        root = PdResolve(src, ar, dc, a, b, st, root);
        // When the file is encrypted, what cannot be read is probably
        // encrypted (object streams are, whole): say so, and let P3.2 decrypt.
        if (root == 0) {
            return PdUnreadable(dc, 4);
        }
        if (Pdflex.PlKindOf(ar, root) != 7) {
            return PdUnreadable(dc, 4);
        }
        emon.Port.CellsSet(dc, DRoot, root);
        pages = PdDget(src, ar, dc, a, b, st, root, Pdfnames.PnPages());
        if (pages == 0) {
            return PdUnreadable(dc, 5);
        }
        if (Pdflex.PlKindOf(ar, pages) != 7) {
            return PdUnreadable(dc, 5);
        }
        return 0;
    }
    internal static int PdElem(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int arr, int i) {
        // The i-th element of an array, resolved; 0 when absent.
        int h = PdNth(ar, arr, i);
        return PdResolve(src, ar, dc, a, b, st, h);
    }
    internal static int PdNumCp(emon.Port.Cells ar, int h) {
        // An int or real object in centipoints; `pd-is-num` says whether it is one.
        return Pdflex.PlNumCp(ar, h);
    }
    internal static int PdIsNum(emon.Port.Cells ar, int h) {
        if (h == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, h) == 2) {
            return 1;
        }
        if (Pdflex.PlKindOf(ar, h) == 3) {
            return 1;
        }
        return 0;
    }
    internal static int PdReadBox(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int boxh, emon.Port.Cells pg, int at) {
        // Read a box (four numbers, any of which may be a reference) into
        // pg[at, at+4) as x0 y0 x1 y1 with x0 < x1 and y0 < y1. Answers 1 when
        // it is a box with a positive area, else 0 and pg untouched.
        if (boxh == 0) {
            return 0;
        }
        int arr = PdResolve(src, ar, dc, a, b, st, boxh);
        int h0 = 0;
        int h1 = 0;
        int h2 = 0;
        int h3 = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int t = 0;
        if (arr == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, arr) != 6) {
            return 0;
        }
        if (Pdflex.PlCount(ar, arr) < 4) {
            return 0;
        }
        h0 = PdElem(src, ar, dc, a, b, st, arr, 0);
        h1 = PdElem(src, ar, dc, a, b, st, arr, 1);
        h2 = PdElem(src, ar, dc, a, b, st, arr, 2);
        h3 = PdElem(src, ar, dc, a, b, st, arr, 3);
        if (PdIsNum(ar, h0) == 0) {
            return 0;
        }
        if (PdIsNum(ar, h1) == 0) {
            return 0;
        }
        if (PdIsNum(ar, h2) == 0) {
            return 0;
        }
        if (PdIsNum(ar, h3) == 0) {
            return 0;
        }
        x0 = PdNumCp(ar, h0);
        y0 = PdNumCp(ar, h1);
        x1 = PdNumCp(ar, h2);
        y1 = PdNumCp(ar, h3);
        if (x0 > x1) {
            t = x0;
            x0 = x1;
            x1 = t;
        }
        if (y0 > y1) {
            t = y0;
            y0 = y1;
            y1 = t;
        }
        if ((x0 == x1) || (y0 == y1)) {
            return 0;
        }
        emon.Port.CellsSet(pg, at, x0);
        emon.Port.CellsSet(pg, at + 1, y0);
        emon.Port.CellsSet(pg, at + 2, x1);
        emon.Port.CellsSet(pg, at + 3, y1);
        return 1;
    }
    internal static int PdRotation(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int rh) {
        // /Rotate as 0, 90, 180 or 270. Negative values wrap; a value that
        // is not a multiple of 90 (poppler keeps 45, pdf.js reads 0) is 0.
        int h = PdResolve(src, ar, dc, a, b, st, rh);
        int cp = 0;
        int deg = 0;
        if (PdIsNum(ar, h) == 0) {
            return 0;
        }
        cp = PdNumCp(ar, h);
        if ((cp % 100) != 0) {
            return 0;
        }
        deg = (cp / 100) % 360;
        if (deg < 0) {
            deg += 360;
        }
        if ((deg % 90) != 0) {
            return 0;
        }
        return deg;
    }
    internal static int PdAddPage(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, int node, int num, int im, int ic, int ir, int ires) {
        // Append the page record for a leaf `node` with its inherited
        // attributes (handles, 0 when no ancestor has one).
        int at = emon.Port.CellsLen(pg);
        int flags = 0;
        int k = 0;
        int ok = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int res = 0;
        int con = 0;
        if ((at / PageStride) >= emon.Port.LimitOf(8)) {
            emon.Port.LimitBreach(8, (at / PageStride) + 1);
        }
        while (k < PageStride) {
            emon.Port.CellsPush(pg, 0);
            k += 1;
        }
        emon.Port.CellsSet(pg, at, node);
        emon.Port.CellsSet(pg, at + 13, num);
        ok = PdReadBox(src, ar, dc, a, b, st, im, pg, at + 1);
        if (ok == 0) {
            emon.Port.CellsSet(pg, at + 1, 0);
            emon.Port.CellsSet(pg, at + 2, 0);
            emon.Port.CellsSet(pg, at + 3, 61200);
            emon.Port.CellsSet(pg, at + 4, 79200);
            flags = 1;
            PdWarnSet(dc, 256);
        }
        ok = PdReadBox(src, ar, dc, a, b, st, ic, pg, at + 5);
        if (ok == 1) {
            // The CropBox is clipped to the MediaBox.
            x0 = emon.Port.CellsAt(pg, at + 5);
            y0 = emon.Port.CellsAt(pg, at + 6);
            x1 = emon.Port.CellsAt(pg, at + 7);
            y1 = emon.Port.CellsAt(pg, at + 8);
            if (x0 < emon.Port.CellsAt(pg, at + 1)) {
                x0 = emon.Port.CellsAt(pg, at + 1);
            }
            if (y0 < emon.Port.CellsAt(pg, at + 2)) {
                y0 = emon.Port.CellsAt(pg, at + 2);
            }
            if (x1 > emon.Port.CellsAt(pg, at + 3)) {
                x1 = emon.Port.CellsAt(pg, at + 3);
            }
            if (y1 > emon.Port.CellsAt(pg, at + 4)) {
                y1 = emon.Port.CellsAt(pg, at + 4);
            }
            if ((x0 >= x1) || (y0 >= y1)) {
                ok = 0;
            } else {
                emon.Port.CellsSet(pg, at + 5, x0);
                emon.Port.CellsSet(pg, at + 6, y0);
                emon.Port.CellsSet(pg, at + 7, x1);
                emon.Port.CellsSet(pg, at + 8, y1);
            }
        }
        if (ok == 0) {
            if (ic != 0) {
                flags += 2;
            }
            emon.Port.CellsSet(pg, at + 5, emon.Port.CellsAt(pg, at + 1));
            emon.Port.CellsSet(pg, at + 6, emon.Port.CellsAt(pg, at + 2));
            emon.Port.CellsSet(pg, at + 7, emon.Port.CellsAt(pg, at + 3));
            emon.Port.CellsSet(pg, at + 8, emon.Port.CellsAt(pg, at + 4));
        }
        emon.Port.CellsSet(pg, at + 9, PdRotation(src, ar, dc, a, b, st, ir));
        res = PdResolve(src, ar, dc, a, b, st, ires);
        if ((res != 0) && (Pdflex.PlKindOf(ar, res) == 7)) {
            emon.Port.CellsSet(pg, at + 10, res);
        }
        con = PdDget(src, ar, dc, a, b, st, node, Pdfnames.PnContents());
        emon.Port.CellsSet(pg, at + 11, con);
        emon.Port.CellsSet(pg, at + 12, flags);
        return 0;
    }
    internal static int PdWalk(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, int node, int num, int depth, int im, int ic, int ir, int ires) {
        // One node of the page tree. `im ic ir ires` are the nearest
        // ancestor's /MediaBox /CropBox /Rotate /Resources (handles, 0 for
        // none). A node with /Kids is an intermediate node, any other is a
        // page. A node met twice, a depth beyond 64, a kid that is missing or
        // not a dictionary: skipped, with a warning.
        if (depth > 64) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, node) != 7) {
            PdWarnSet(dc, 128);
            return 0;
        }
        int at = 0;
        int m = im;
        int c = ic;
        int r = ir;
        int res = ires;
        int v = 0;
        int kids = 0;
        int k = 0;
        int kn = 0;
        int kh = 0;
        int kk = 0;
        if (num > 0) {
            at = DFirst + (num * 5);
            if (((emon.Port.CellsAt(dc, at + 4) / 4) & 1) == 1) {
                PdWarnSet(dc, 128);
                return 0;
            }
            emon.Port.CellsSet(dc, at + 4, emon.Port.CellsAt(dc, at + 4) + 4);
        }
        v = Pdflex.PlDictGet(ar, node, Pdfnames.PnMediaBox());
        if (v != 0) {
            m = v;
        }
        v = Pdflex.PlDictGet(ar, node, Pdfnames.PnCropBox());
        if (v != 0) {
            c = v;
        }
        v = Pdflex.PlDictGet(ar, node, Pdfnames.PnRotate());
        if (v != 0) {
            r = v;
        }
        v = Pdflex.PlDictGet(ar, node, Pdfnames.PnResources());
        if (v != 0) {
            res = v;
        }
        kids = PdDget(src, ar, dc, a, b, st, node, Pdfnames.PnKids());
        if ((kids != 0) && (Pdflex.PlKindOf(ar, kids) == 6)) {
            k = Pdflex.PlFirst(ar, kids);
            while (k != 0) {
                kk = Pdflex.PlKindOf(ar, k);
                if (kk == 9) {
                    kn = Pdflex.PlIntValue(ar, k);
                    kh = PdGet(src, ar, dc, a, b, st, kn);
                    if (kh == 0) {
                        PdWarnSet(dc, 128);
                    } else {
                        PdWalk(src, ar, dc, a, b, st, pg, kh, kn, depth + 1, m, c, r, res);
                    }
                } else if (kk == 7) {
                    PdWalk(src, ar, dc, a, b, st, pg, k, 0, depth + 1, m, c, r, res);
                } else {
                    PdWarnSet(dc, 128);
                }
                k = Pdflex.PlNext(ar, k);
            }
            return 0;
        }
        PdAddPage(src, ar, dc, a, b, st, pg, node, num, m, c, r, res);
        return 0;
    }
    public static int PdPages(byte[] src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg) {
        // Walk the page tree from the catalog into `pg` (cleared first) and
        // answer the number of pages. Call it after a successful `pd-open`.
        emon.Port.CellsDrop(pg, 0);
        int root = emon.Port.CellsAt(dc, DRoot);
        int raw = Pdflex.PlDictGet(ar, root, Pdfnames.PnPages());
        int top = PdResolve(src, ar, dc, a, b, st, raw);
        int num = 0;
        int i = 0;
        if (top == 0) {
            return 0;
        }
        // Clear the `visited` marks of an earlier walk.
        while (i < emon.Port.CellsAt(dc, DNent)) {
            if (((emon.Port.CellsAt(dc, (DFirst + (i * 5)) + 4) / 4) & 1) == 1) {
                emon.Port.CellsSet(dc, (DFirst + (i * 5)) + 4, emon.Port.CellsAt(dc, (DFirst + (i * 5)) + 4) - 4);
            }
            i += 1;
        }
        if (Pdflex.PlKindOf(ar, raw) == 9) {
            num = Pdflex.PlIntValue(ar, raw);
        }
        PdWalk(src, ar, dc, a, b, st, pg, top, num, 0, 0, 0, 0, 0);
        return emon.Port.CellsLen(pg) / PageStride;
    }
    public static int PdPgCount(emon.Port.Cells pg) {
        return emon.Port.CellsLen(pg) / PageStride;
    }
    public static int PdPgNode(emon.Port.Cells pg, int i) {
        return emon.Port.CellsAt(pg, i * PageStride);
    }
    public static int PdPgMedia(emon.Port.Cells pg, int i, int k) {
        // MediaBox x0 y0 x1 y1 (k 0..3) in centipoints.
        return emon.Port.CellsAt(pg, (i * PageStride) + (1 + k));
    }
    public static int PdPgCrop(emon.Port.Cells pg, int i, int k) {
        // CropBox, clipped to the MediaBox (the MediaBox when absent).
        return emon.Port.CellsAt(pg, (i * PageStride) + (5 + k));
    }
    public static int PdPgRotate(emon.Port.Cells pg, int i) {
        return emon.Port.CellsAt(pg, (i * PageStride) + 9);
    }
    public static int PdPgResources(emon.Port.Cells pg, int i) {
        return emon.Port.CellsAt(pg, (i * PageStride) + 10);
    }
    public static int PdPgContents(emon.Port.Cells pg, int i) {
        return emon.Port.CellsAt(pg, (i * PageStride) + 11);
    }
    public static int PdPgFlags(emon.Port.Cells pg, int i) {
        return emon.Port.CellsAt(pg, (i * PageStride) + 12);
    }
    public static int PdPgObjnum(emon.Port.Cells pg, int i) {
        return emon.Port.CellsAt(pg, (i * PageStride) + 13);
    }
    internal static int PdEmitCp(System.Text.StringBuilder t, int v) {
        // A centipoint value as a JSON number, SPEC 4.3: 7250 is 72.5, -5 is
        // -0.05, 0 is 0, no trailing zeros.
        int m = v;
        int frac = 0;
        if (m < 0) {
            emon.Port.TextAscii(t, "-");
            m = 0 - m;
        }
        emon.Port.TextI32(t, m / 100);
        frac = m % 100;
        if (frac != 0) {
            emon.Port.TextAscii(t, ".");
            emon.Port.TextCp(t, 48 + (frac / 10));
            if ((frac % 10) != 0) {
                emon.Port.TextCp(t, 48 + (frac % 10));
            }
        }
        return 0;
    }
    internal static int PdEmitBox(System.Text.StringBuilder t, emon.Port.Cells pg, int i, int crop) {
        emon.Port.TextAscii(t, "[");
        int k = 0;
        while (k < 4) {
            if (k > 0) {
                emon.Port.TextAscii(t, ",");
            }
            if (crop == 1) {
                PdEmitCp(t, PdPgCrop(pg, i, k));
            } else {
                PdEmitCp(t, PdPgMedia(pg, i, k));
            }
            k += 1;
        }
        emon.Port.TextAscii(t, "]");
        return 0;
    }
    public static int PdSourceJson(System.Text.StringBuilder t, emon.Port.Cells dc, emon.Port.Cells pg) {
        // The `Source` value of a PDF (SPEC 2.0) as canonical JSON: the
        // format, the version from the header, whether the trailer names an
        // encryption dictionary, and every page's boxes (centipoints as
        // decimal points, SPEC 4.3) and rotation. Stage 0 grows more fields
        // (P3.9 metadata, P3.7 structure, P3.8 forms) and they are appended
        // here, in this order.
        int n = PdPgCount(pg);
        int i = 0;
        emon.Port.TextAscii(t, "{\"format\":\"pdf\",\"version\":\"");
        emon.Port.TextI32(t, PdVersionMajor(dc));
        emon.Port.TextAscii(t, ".");
        emon.Port.TextI32(t, PdVersionMinor(dc));
        emon.Port.TextAscii(t, "\",\"encrypted\":");
        if (PdEncrypted(dc) == 1) {
            emon.Port.TextAscii(t, "true");
        } else {
            emon.Port.TextAscii(t, "false");
        }
        emon.Port.TextAscii(t, ",\"pageCount\":");
        emon.Port.TextI32(t, n);
        emon.Port.TextAscii(t, ",\"pages\":[");
        while (i < n) {
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            emon.Port.TextAscii(t, "{\"media\":");
            PdEmitBox(t, pg, i, 0);
            emon.Port.TextAscii(t, ",\"crop\":");
            PdEmitBox(t, pg, i, 1);
            emon.Port.TextAscii(t, ",\"rotate\":");
            emon.Port.TextI32(t, PdPgRotate(pg, i));
            emon.Port.TextAscii(t, "}");
            i += 1;
        }
        emon.Port.TextAscii(t, "]}");
        return 0;
    }
}
